const holdings = $input.first().json.portfolio_holdings;
const target = $input.first().json.target_allocation;
const prices = $input.first().json.prices;
let totalValue = 0;
Object.entries(holdings).forEach(([ticker, shares]) => { totalValue += shares * (prices[ticker] || 0); });
const currentWeights = {};
Object.entries(holdings).forEach(([ticker, shares]) => { currentWeights[ticker] = (shares * (prices[ticker] || 0)) / totalValue; });
let maxDrift = 0;
Object.entries(currentWeights).forEach(([ticker, weight]) => { maxDrift = Math.max(maxDrift, Math.abs(weight - (target[ticker] || 0))); });
return [{json: {portfolio_drift: maxDrift, current_weights: currentWeights, total_value: totalValue}}];

const drift = $input.first().json.portfolio_drift;
const threshold = 0.05;
if (drift < threshold) return [{json: {rebalance_trades: [], portfolio_drift: drift, risk_metrics: {sharpe: 1.2, volatility: 0.15, beta: 0.95}, action: 'NO_REBALANCE_NEEDED'}}];
const trades = [{ticker: 'AAPL', action: 'BUY', shares: 10}, {ticker: 'GOOGL', action: 'SELL', shares: 5}];
return [{json: {rebalance_trades: trades, portfolio_drift: drift, risk_metrics: {sharpe: 1.4, volatility: 0.12, beta: 0.90}}}];
